// ==/BuiltInOrbs==

namespace {

const BuiltInOrb* FindBuiltInOrb(std::wstring const& id) {
    for (BuiltInOrb const& orb : kBuiltInOrbs) {
        if (_wcsicmp(orb.id, id.c_str()) == 0) {
            return &orb;
        }
    }
    return nullptr;
}

}  // namespace
